import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using Claude to interact with the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Transaction memo/reason"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with the reason: {reason}. Use the ledger_post tool and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to extract the tool call
    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use":
                # Simulate the ledger post operation
                tool_input = block.input
                # In a real scenario, this would call the actual ledger module
                # For now, we'll generate a mock entry id
                entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"

                # Continue the conversation with the tool result
                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": block.id,
                            "content": f"Successfully posted transfer. Entry ID: {entry_id}"
                        }
                    ]
                })

                # Get final response
                final_response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=tools,
                    messages=messages
                )

                # Extract entry id from the response
                for final_block in final_response.content:
                    if hasattr(final_block, 'text'):
                        # Look for the entry id in the response
                        if "entry_" in final_block.text:
                            import re
                            match = re.search(r'entry_\w+_\d+_\d+', final_block.text)
                            if match:
                                return match.group(0)

                return entry_id

    return ""
