def _raise_malformed(message: str) -> NoReturn:
    try:
        import ledger  # type: ignore

        post_error = getattr(ledger, "PostError", None)
    except Exception:
        post_error = None

    if isinstance(post_error, type) and issubclass(post_error, Exception):
        try:
            raise post_error(message)
        except TypeError:
            raise post_error()

    raise ValueError(message)


