    if not isinstance(dollars, str):
        _raise_malformed("amount must be a string")

    amount = dollars.strip()
    match = _MONEY_RE.fullmatch(amount)
    if match is None:
        _raise_malformed("malformed amount")

    sign, whole, frac_a, frac_b = match.groups()
    whole = whole or "0"
    frac = (frac_a if frac_a is not None else frac_b) or ""

    cents = int(whole) * 100 + int(frac.ljust(2, "0"))
    if sign == "-" and cents != 0:
        cents = -cents

    return str(cents)

