import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post function
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Memo or reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer of {cents} cents to account {acct} with reason '{reason}' using the post function."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to find the tool use block
    for block in response.content:
        if block.type == "tool_use" and block.name == "post":
            # Extract the entry_id from the tool use input
            # In a real implementation, this would actually call the ledger module
            # For now, we'll return a simulated entry id based on the input
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"
            return entry_id

    # If no tool use was found, raise an error
    raise ValueError("Failed to generate a valid transfer")


if __name__ == "__main__":
