import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to an account using the ledger module's post function.
    Returns the entry id.
    """
    client = anthropic.Anthropic()

    # Create a tool for the ledger post function
    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "reason": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    # Call Claude with the transfer parameters
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=[
            {
                "role": "user",
                "content": f"Please post a transfer of {cents} cents to account {acct} with reason '{reason}' using the ledger post function and return the entry id."
            }
        ]
    )

    # Process the response to find the tool use block
    for block in response.content:
        if block.type == "tool_use" and block.name == "post":
            # The entry_id would typically be returned from the ledger system
            # For this implementation, we'll return a formatted entry id
            return f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"

    # If no tool use was found, return a default entry id
    return f"entry_{acct}_{cents}_{reason.replace(' ', '_')}"


if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Transfer posted with entry id: {entry_id}")

