import anthropic

client = anthropic.Anthropic()

# Track entry IDs
_entry_counter = 0
_entries = {}

def post(acct: str, cents: int, reason: str) -> int:
    """Post cents to account acct using reason as the memo, and return the entry id."""
    global _entry_counter
    _entry_counter += 1
    entry_id = _entry_counter

    _entries[entry_id] = {
        'account': acct,
        'amount_cents': cents,
        'reason': reason,
        'entry_id': entry_id
    }

    return entry_id

def transfer(acct: str, cents: int, reason: str) -> int:
    """Transfer cents to account acct using reason as the memo, and return the entry id."""
    return post(acct, cents, reason)

def process_tool_call(tool_name: str, tool_input: dict) -> str:
    """Process tool calls from Claude."""
    if tool_name == "post":
        acct = tool_input.get("acct")
        cents = tool_input.get("cents")
        reason = tool_input.get("reason")
        entry_id = transfer(acct, cents, reason)
        return f"Posted {cents} cents to account {acct} with reason '{reason}'. Entry ID: {entry_id}"
    return "Unknown tool"

def get_tool_definition():
    """Get the tool definition for Claude."""
    return {
        "name": "post",
        "description": "Post an amount in cents to a ledger account with a reason/memo",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "reason": {
                    "type": "string",
                    "description": "The reason or memo for the transaction"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }

def run_with_claude(user_message: str) -> str:
    """Run a request through Claude using the post tool."""
    messages = [
        {"role": "user", "content": user_message}
    ]

    tools = [get_tool_definition()]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if not tool_use_block:
            break

        tool_name = tool_use_block.name
        tool_input = tool_use_block.input
        tool_use_id = tool_use_block.id

        tool_result = process_tool_call(tool_name, tool_input)

        messages = [
            {"role": "user", "content": user_message},
            {"role": "assistant", "content": response.content},
            {
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_id,
                        "content": tool_result,
                    }
                ],
            },
        ]

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    final_response = ""
    for block in response.content:
        if hasattr(block, "text"):
            final_response += block.text

    return final_response

if __name__ == "__main__":
    print("Testing transfer function directly...")
    entry_id = transfer("savings", 5000, "Initial deposit")
    print(f"Direct transfer returned entry ID: {entry_id}")
    print(f"Stored entries: {_entries}")

    print("\nTesting with Claude...")
    result = run_with_claude("Post 1000 cents to my checking account with the reason 'paycheck'")
    print(f"Claude response: {result}")
    print(f"Final entries: {_entries}")
