def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the team's private wire format."""
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    stripped = dollars.strip()
    if not stripped:
        raise ValueError("empty amount string")

    # Determine sign
    sign = ""
    if stripped.startswith("-"):
        sign = "-"
        stripped = stripped[1:]
    elif stripped.startswith("+"):
        stripped = stripped[1:]

    # Split integer and fractional parts
    if "." in stripped:
        int_part, frac_part = stripped.split(".", 1)
    else:
        int_part, frac_part = stripped, ""

    # Validate and normalize integer part
    if not int_part:
        int_part = "0"
    elif not int_part.isdigit():
        raise ValueError(f"invalid integer part: {int_part!r}")
    else:
        int_part = int_part.lstrip("0") or "0"

    # Validate and normalize fractional part
    if not frac_part:
        frac_part = "00"
    elif len(frac_part) == 1:
        if not frac_part.isdigit():
            raise ValueError(f"invalid fractional part: {frac_part!r}")
        frac_part += "0"
    elif len(frac_part) == 2:
        if not frac_part.isdigit():
            raise ValueError(f"invalid fractional part: {frac_part!r}")
    else:
        raise ValueError(f"fractional part must be at most 2 digits: {frac_part!r}")

    # Remove leading zeros from integer part
    digits = str(int(int_part))

    return f"{sign}{digits}.{frac_part}"

