def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to wire format.

    The wire format is the signed integer number of cents as a decimal string.
    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0'      -> '0'
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = ""
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
    else:
        whole, frac = s, ""

    if not (whole + frac).isdigit():
        raise ValueError(f"malformed amount: {dollars!r}")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        raise ValueError(f"too many fractional digits: {dollars!r}")
    frac = (frac + "00")[:2]

    whole = whole or "0"
    cents = int(whole) * 100 + int(frac)

    if cents == 0:
        return "0"

    return f"{sign}{cents}"

