def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the
    team's private wire format.

    The wire format encodes the amount as an integer number of cents,
    preserving sign, as a decimal string. This avoids floating point
    and keeps the representation canonical and unambiguous.

    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0.00'   -> '0'
        '100'    -> '10000'
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in '+-':
        negative = s[0] == '-'
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if '.' in s:
        whole, _, frac = s.partition('.')
        if '.' in frac:
            raise ValueError("multiple decimal points")
    else:
        whole, frac = s, ''

    # Allow empty whole (e.g. '.07') or empty frac (e.g. '12.')
    whole = whole or '0'
    frac = frac or ''

    if not whole.isdigit():
        raise ValueError("invalid whole part")
    if frac and not frac.isdigit():
        raise ValueError("invalid fractional part")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        raise ValueError("more than cents precision not supported")
    frac = frac.ljust(2, '0')

    cents = int(whole) * 100 + int(frac)

    if negative and cents != 0:
        return '-' + str(cents)
    return str(cents)

