import anthropic
import json

ledger_module_schema = {
    "name": "ledger",
    "description": "A ledger system for managing financial transactions",
    "tools": [
        {
            "name": "post",
            "description": "Posts a transaction to an account ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }
    ]
}


def transfer(acct, cents, reason):
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Reason/memo for the transaction

    Returns:
        The entry id of the posted transaction
    """
    client = anthropic.Anthropic()

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{reason}'. Return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=[{
            "name": "post",
            "description": "Posts a transaction to an account ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }],
        messages=messages
    )

    for content_block in response.content:
        if content_block.type == "tool_use":
            tool_name = content_block.name
            tool_input = content_block.input

            if tool_name == "post":
                entry_id = f"entry_{tool_input['account']}_{tool_input['amount_cents']}_{hash(tool_input['memo']) % 10000}"
                return entry_id

    return None
