import json

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Post a transfer to an account using Claude to call the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry id of the posted transaction
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Transaction memo/reason"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason: {reason}. Use the post tool to complete this transaction."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use" and block.name == "post":
                tool_input = block.input

                import ledger
                entry_id = ledger.post(
                    acct=tool_input["acct"],
                    cents=tool_input["cents"],
                    memo=tool_input["memo"]
                )
                return str(entry_id)

    raise RuntimeError("Failed to post transfer using Claude")
