def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the
    team's private wire format.

    The wire format encodes the amount as an integer number of cents
    with an explicit sign, formatted as a decimal string prefixed by a
    scale marker. Examples:
        '12.30'  -> 'c:+1230'
        '-0.07'  -> 'c:-7'
        '0'      -> 'c:+0'
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        int_part, _, frac_part = s.partition(".")
        if "." in frac_part:
            raise ValueError("malformed amount")
    else:
        int_part, frac_part = s, ""

    if int_part == "":
        int_part = "0"

    if not int_part.isdigit():
        raise ValueError("malformed integer part")
    if frac_part and not frac_part.isdigit():
        raise ValueError("malformed fractional part")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac_part) > 2:
        # Reject sub-cent precision rather than silently truncating.
        if frac_part[2:].strip("0"):
            raise ValueError("sub-cent precision not supported")
        frac_part = frac_part[:2]
    frac_part = frac_part.ljust(2, "0")

    cents = int(int_part) * 100 + int(frac_part)

    # Canonicalize negative zero to positive zero.
    if cents == 0:
        sign = "+"

    return "c:{}{}".format(sign, cents)

