import anthropic


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using Claude to interact with the ledger module.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry id from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger module",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason '{reason}' using the ledger module's post function. Return the entry id."
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block and tool_use_block.name == "ledger_post":
                import ledger

                input_params = tool_use_block.input
                entry_id = ledger.post(
                    input_params["account"],
                    input_params["cents"],
                    input_params["memo"]
                )

                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": str(entry_id)
                        }
                    ]
                })

                return entry_id
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    text = block.text
                    if 'entry_id' in text.lower() or 'id' in text.lower():
                        words = text.split()
                        for i, word in enumerate(words):
                            if word.lower() in ['id:', 'entry_id:'] and i + 1 < len(words):
                                return words[i + 1].strip('.,')

            return ""

