def encode_amount(dollars: str) -> str:
    # Parse sign
    if dollars.startswith('-'):
        sign = '-'
        numeric_part = dollars[1:]
    else:
        sign = '+'
        numeric_part = dollars

    # Split into dollars and cents
    if '.' in numeric_part:
        dollars_part, cents_part = numeric_part.split('.', 1)
    else:
        dollars_part = numeric_part
        cents_part = ''

    # Pad/truncate cents to exactly 2 digits
    if len(cents_part) == 0:
        cents_part = '00'
    elif len(cents_part) == 1:
        cents_part = cents_part + '0'
    else:
        cents_part = cents_part[:2]

    # Remove any leading zeros from dollars part, but keep at least one digit
    dollars_part = dollars_part.lstrip('0')
    if dollars_part == '':
        dollars_part = '0'

    # Combine into total minor units (cents) as string
    if dollars_part == '0':
        digits = cents_part.lstrip('0')
        if digits == '':
            digits = '0'
    else:
        # dollars_part could still have leading zeros removed, so just concatenate
        digits = dollars_part + cents_part

    # Compute check digit: sum of decimal digits mod 10
    check = sum(int(ch) for ch in digits) % 10

    # Build result
    return f"{sign}{digits}#{check}"

