        dollars = dollars[1:]
    elif dollars.startswith('+'):
        dollars = dollars[1:]

    int_part, frac_part = dollars.split('.')

    if len(frac_part) > 2:
        frac_part = frac_part[:2]
    elif len(frac_part) < 2:
        frac_part = frac_part.ljust(2, '0')

    if int_part == '':
