import anthropic
import json

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account using reason as memo via Claude.
    Uses the ledger module's post function through Claude's tool use.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post_transfer",
            "description": "Post a transfer to an account in the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "Account identifier"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents to transfer"
                    },
                    "reason": {
                        "type": "string",
                        "description": "Memo or reason for the transfer"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason '{reason}' using the ledger's post function. Return the entry ID."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    entry_id = None
