def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer cents to account using reason as memo via Claude.
    Uses the ledger module's post function through Claude's tool use.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post_transfer",
            "description": "Post a transfer to an account in the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
