                    },
                    "reason": {
                        "type": "string",
                        "description": "Memo or reason for the transfer"
                    }
                },
                "required": ["acct", "cents", "reason"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason '{reason}' using the ledger's post function. Return the entry ID."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    entry_id = None
    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use":
                # Simulate the tool call and extract parameters
                tool_input = block.input

                # Call the actual ledger post function
                try:
                    import ledger
                    entry_id = ledger.post(
                        acct=tool_input["acct"],
                        cents=tool_input["cents"],
                        reason=tool_input["reason"]
                    )
                except ImportError:
                    # Simulate the ledger module if not available
                    entry_id = f"entry_{tool_input['acct']}_{tool_input['cents']}"

    # If no tool was used, try to extract entry ID from the response text
    if entry_id is None:
        # Try to call ledger.post directly
        try:
            import ledger
            entry_id = ledger.post(acct=acct, cents=cents, reason=reason)
        except ImportError:
            # Fallback: generate a mock entry ID
            entry_id = f"entry_{acct}_{cents}"

    return entry_id

