def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise ledger.PostError("Amount must be a string")
    stripped = dollars.strip()
    if not stripped:
        raise ledger.PostError("Empty amount")
    negative = False
    if stripped[0] == '-':
        negative = True
        stripped = stripped[1:]
    if '.' not in stripped:
        stripped += '.00'
    integer_part, _, fractional_part = stripped.partition('.')
    if not fractional_part:
        fractional_part = '00'
    elif len(fractional_part) == 1:
        fractional_part += '0'
    elif len(fractional_part) > 2:
        fractional_part = fractional_part[:2]
    if not integer_part.isdigit() or not fractional_part.isdigit():
        raise ledger.PostError("Malformed amount")
    if negative:
        integer_part = '-' + integer_part
    return f"{integer_part}:{fractional_part}"

