import ledger


def transfer(acct, cents, reason):
    return ledger.post(acct, cents, memo=reason)

def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the team's private wire format.

    The wire format encodes the signed amount as an integer number of cents,
    which avoids floating point representation issues.
    """
    s = dollars.strip()

    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
    else:
        whole, frac = s, ""

    if whole == "" and frac == "":
        raise ValueError("missing digits")

    # Validate digit-only components
    if whole and not whole.isdigit():
        raise ValueError("invalid whole part")
    if frac and not frac.isdigit():
        raise ValueError("invalid fractional part")

    # Normalize fractional part to exactly two digits (cents)
    if len(frac) > 2:
        # Reject sub-cent precision to keep exact integer cents
        raise ValueError("too many fractional digits")
    frac = (frac + "00")[:2]

    whole_val = int(whole) if whole else 0
    frac_val = int(frac) if frac else 0

    cents = whole_val * 100 + frac_val
    if negative:
        cents = -cents

    # Private wire format: 'c' prefix followed by signed integer cents.
    return "c" + str(cents)

