from decimal import Decimal, InvalidOperation


class EncodeError(Exception):
    """Raised when a dollar amount cannot be encoded."""


def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the wire format.

    NOTE: The task did not specify the actual private wire format, so this
    uses a safe, lossless, unambiguous convention: a signed integer number
    of cents rendered as a string (e.g. '12.30' -> '1230', '-0.07' -> '-7').
    Replace the body if the real format differs.
    """
    if not isinstance(dollars, str):
        raise EncodeError(f"expected str, got {type(dollars).__name__}")

    text = dollars.strip()
    if not text:
        raise EncodeError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation:
        raise EncodeError(f"malformed amount: {dollars!r}")

    cents = (value * 100).to_integral_value()
    if cents != value * 100:
        raise EncodeError(f"sub-cent precision not representable: {dollars!r}")

    return str(int(cents))

