                    account=tool_input["account"],
                    amount=tool_input["amount"],
                    memo=tool_input["memo"]
                )

    # If Claude didn't use the tool, fall back to direct posting
    if entry_id is None:
        entry_id = post(account=acct, amount=cents, memo=reason)

