import anthropic

def transfer(acct, cents, reason):
    """Transfer funds and post to ledger."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "number",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with memo '{reason}' and return the entry id"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process tool use
    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block and tool_use_block.name == "post":
            # Simulate the tool response - in a real system this would call the actual ledger
            tool_input = tool_use_block.input
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"

            # Add the assistant's response and tool result to messages
            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": f"Successfully posted {cents} cents to {acct} with entry id: {entry_id}"
                    }
                ]
            })

            # Get the next response
            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )
        else:
            break

    # Extract entry id from the response
    for block in response.content:
        if hasattr(block, 'text'):
            if 'entry_' in block.text:
                # Extract entry id from text
                import re
                match = re.search(r'entry_\w+', block.text)
                if match:
                    return match.group(0)

    # Fallback: generate entry id based on inputs
    return f"entry_{acct}_{cents}_{hash(reason) % 10000}"
