def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the team's private wire format.

    The wire format encodes the amount as an integer number of cents,
    preserving sign, with no decimal point.
    """
    s = dollars.strip()

    if not s:
        raise ValueError("empty amount")

    sign = ""
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("malformed amount")

    if "." in s:
        int_part, _, frac_part = s.partition(".")
    else:
        int_part, frac_part = s, ""

    if int_part == "":
        int_part = "0"

    if not int_part.isdigit():
        raise ValueError("malformed amount")

    if frac_part != "" and not frac_part.isdigit():
        raise ValueError("malformed amount")

    # Normalize fractional part to exactly two digits (cents).
    if len(frac_part) > 2:
        raise ValueError("too many fractional digits")
    frac_part = (frac_part + "00")[:2]

    cents = int(int_part) * 100 + int(frac_part)

    if cents == 0:
        sign = ""

    return f"{sign}{cents}"

