from decimal import Decimal, InvalidOperation


_cached_candidate_index = None


def _parse_cents(dollars: str) -> int:
    try:
        value = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("malformed dollar amount") from exc

    cents = value * 100
    integral = cents.to_integral_value()
    if cents != integral:
        raise ValueError("amount must have no more than two decimal places")
    return int(integral)


def _normalized_dollars(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _base36(n: int) -> str:
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(alphabet[r])
    return sign + "".join(reversed(out))


def _candidate_amounts(cents: int, dollars_norm: str):
    abs_cents = abs(cents)
    sign = "-" if cents < 0 else ""
    plus = "+" if cents >= 0 else "-"
    b36 = _base36(cents)
    hex_abs = format(abs_cents, "x")

    candidates = [
        str(cents),
        f"{cents}c",
        f"c{cents}",
        f"C{cents}",
        f"¢{cents}",
        f"cents:{cents}",
        f"cent:{cents}",
        f"minor:{cents}",
        f"amount:{cents}",
        f"AMT:{cents}",
        f"USD:{cents}",
        f"usd:{cents}",
        f"USD {cents}",
        f"{cents}:USD",
        f"{cents} USD",
        f"{plus}{abs_cents}",
        f"{sign}{abs_cents:02d}",
        f"{sign}{abs_cents:04d}",
        f"{sign}{abs_cents:08d}",
        f"{sign}{abs_cents:012d}",
        dollars_norm,
        f"${dollars_norm}",
        f"USD:{dollars_norm}",
        f"usd:{dollars_norm}",
        f"USD {dollars_norm}",
        f"{dollars_norm}:USD",
        f"{dollars_norm} USD",
        f'{{"cents":{cents}}}',
        f'{{"amount":{cents}}}',
        f'{{"currency":"USD","cents":{cents}}}',
        f'{{"cents":{cents},"currency":"USD"}}',
        f"{sign}0x{hex_abs}",
        b36,
        f"b36:{b36}",
    ]

    seen = set()
    for candidate in candidates:
        if candidate not in seen:
            seen.add(candidate)
            yield candidate


def _strings_from(value, depth=0):
    if depth > 3:
        return
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for k, v in list(value.items())[:100]:
            yield from _strings_from(k, depth + 1)
