from decimal import Decimal, InvalidOperation


_cached_candidate_index = None


def _parse_cents(dollars: str) -> int:
    try:
        value = Decimal(str(dollars).strip())
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("malformed dollar amount") from exc

    cents = value * 100
    integral = cents.to_integral_value()
    if cents != integral:
        raise ValueError("amount must have no more than two decimal places")
    return int(integral)


def _normalized_dollars(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _base36(n: int) -> str:
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, 36)
        out.append(alphabet[r])
    return sign + "".join(reversed(out))


def _candidate_amounts(cents: int, dollars_norm: str):
    abs_cents = abs(cents)
