        f"{plus}{abs_cents}",
        f"{sign}{abs_cents:02d}",
        f"{sign}{abs_cents:04d}",
        f"{sign}{abs_cents:08d}",
        f"{sign}{abs_cents:012d}",
        dollars_norm,
