        f"usd:{dollars_norm}",
        f"USD {dollars_norm}",
        f"{dollars_norm}:USD",
        f"{dollars_norm} USD",
        f'{{"cents":{cents}}}',
        f'{{"amount":{cents}}}',
        f'{{"currency":"USD","cents":{cents}}}',
        f'{{"cents":{cents},"currency":"USD"}}',
        f"{sign}0x{hex_abs}",
