import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:(?:\d+(?:\.\d{0,2})?)|(?:\.\d{1,2}))$")


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not _AMOUNT_RE.fullmatch(s):
        raise ValueError("malformed dollar amount")

    sign = -1 if s.startswith("-") else 1
    if s[:1] in "+-":
        s = s[1:]

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    whole_cents = int(whole or "0") * 100
    frac_cents = int((frac + "00")[:2])
    cents = sign * (whole_cents + frac_cents)

    return str(cents)

