import re

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Mock ledger module for demonstration
class MockLedgerModule:
    _entries = {}
    _next_id = 1

    @staticmethod
    def post(acct, cents, reason):
        entry_id = MockLedgerModule._next_id
        MockLedgerModule._entries[entry_id] = {
            "account": acct,
            "cents": cents,
            "reason": reason,
            "entry_id": entry_id
        }
        MockLedgerModule._next_id += 1
        return entry_id

# Create a mock ledger module
ledger = MockLedgerModule()

# Define tools for Claude to use
tools = [
    {
        "name": "post_to_ledger",
        "description": "Posts a transaction to the ledger system",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "reason": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["account", "cents", "reason"]
        }
    }
]

def transfer(acct, cents, reason):
    """
    Transfer funds using Claude and the ledger module.
    Uses Claude to determine how to properly post the transaction.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        The entry ID from the ledger
    """

    # Create the initial message to Claude
    user_message = f"""I need to post a transfer to the ledger system.
Account: {acct}
Amount in cents: {cents}
Reason: {reason}

Please use the post_to_ledger tool to complete this transfer and tell me the entry ID."""

    messages = [
        {"role": "user", "content": user_message}
    ]

    # First API call - Claude decides what to do
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    entry_id = None

    # Check if Claude wants to use a tool
    if response.stop_reason == "tool_use":
        # Find the tool use block
        for block in response.content:
            if block.type == "tool_use":
                if block.name == "post_to_ledger":
                    # Extract the parameters
                    params = block.input
                    # Call the actual ledger post function
                    entry_id = ledger.post(
                        params["account"],
                        params["cents"],
                        params["reason"]
                    )

                    # Continue the conversation with the result
                    tool_result = f"Transaction posted successfully. Entry ID: {entry_id}"

                    # Add Claude's response and tool result to messages
                    messages.append({"role": "assistant", "content": response.content})
                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": block.id,
                                "content": tool_result
                            }
                        ]
                    })

                    # Get Claude's final response
                    final_response = client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=1024,
                        tools=tools,
                        messages=messages
                    )

                    # Extract entry_id from the final response if needed
                    for final_block in final_response.content:
                        if hasattr(final_block, 'text'):
                            # Look for entry ID in the response
                            text = final_block.text
                            # Try to extract entry ID from response
                            match = re.search(r'Entry ID:\s*(\d+)', text)
                            if match:
                                entry_id = int(match.group(1))

    return entry_id

if __name__ == "__main__":
    # Test the transfer function
    test_entry_id = transfer("checking", 10000, "Monthly salary deposit")
    print(f"Transfer completed with entry ID: {test_entry_id}")

    # Verify the entry was recorded
