def encode_amount(dollars_str: str) -> str:
    """Serialize a money amount string to the team's private wire format."""

    # Validate basic structure
    if not isinstance(dollars_str, str):
        raise ValueError("Input must be a string")

    stripped = dollars_str.strip()
    if not stripped:
        raise ValueError("Empty amount string")

    # Determine sign
    sign = ""
    if stripped.startswith("-"):
        sign = "-"
        magnitude = stripped[1:]
    elif stripped.startswith("+"):
        magnitude = stripped[1:]
    else:
        magnitude = stripped

    # Must have exactly one decimal point
    if "." not in magnitude:
        raise ValueError("Amount must include decimal point")

    parts = magnitude.split(".")
    if len(parts) != 2:
        raise ValueError("Invalid decimal format")

    dollars_part, cents_part = parts

    # Validate dollars part (can be empty for values like ".50", "0" by itself, etc.)
    if dollars_part == "":
        dollars_part = "0"
    else:
        if not dollars_part.isdigit():
            raise ValueError("Non-digit characters in dollars portion")
        # Remove leading zeros for canonical form
        dollars_part = str(int(dollars_part))

    # Validate cents part (must be exactly 2 digits)
    if len(cents_part) != 2:
        raise ValueError("Cents must be exactly 2 digits")
    if not cents_part.isdigit():
        raise ValueError("Non-digit characters in cents portion")

    # Build wire format: sign + dollars + cents (no decimal point)
    result = f"{sign}{dollars_part}{cents_part}"

    # Edge case: "-0.00" should be "000", not "-000"
    if result == "-0" + cents_part and int(cents_part) == 0:
        result = "0" + cents_part

    return result

