                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason: {reason}. Use the post tool and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    for content_block in response.content:
        if content_block.type == "tool_use":
            if content_block.name == "post":
                # Simulate the ledger.post function
                tool_input = content_block.input
                entry_id = f"entry_{hash(str(tool_input)) % 10000000}"
                return entry_id

    # If no tool was used, try to extract from text response
    for content_block in response.content:
        if hasattr(content_block, 'text'):
            text = content_block.text
            # Try to find entry id in the response
            if 'entry' in text.lower():
                import re
                match = re.search(r'entry[_-]?\w+', text, re.IGNORECASE)
                if match:
                    return match.group(0)

    return "entry_unknown"

