# solution.py
def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to the team's private wire format."""
    # Validate basic structure
    stripped = dollars.strip()
    if not stripped:
        raise ValueError("Empty amount string")

    # Handle optional sign
    sign = ''
    if stripped[0] in ('+', '-'):
        sign = stripped[0]
        stripped = stripped[1:]
        if not stripped:
            raise ValueError("Sign with no digits")

    # Must have at most one decimal point
    if stripped.count('.') > 1:
        raise ValueError("Multiple decimal points")

    # Split into integer and fractional parts
    if '.' in stripped:
        integer_part, frac_part = stripped.split('.')
    else:
        integer_part, frac_part = stripped, ''

    # Validate integer part (must be digits, optional leading zeros allowed)
    if not integer_part:
        integer_part = '0'
    if not integer_part.isdigit():
        raise ValueError(f"Invalid integer part: {integer_part}")

    # Normalize integer part: remove leading zeros but keep at least one digit
    integer_part = integer_part.lstrip('0') or '0'

    # Validate and pad fractional part to exactly 2 digits
    if not frac_part:
        frac_part = '00'
    elif len(frac_part) == 1:
        frac_part = frac_part + '0'
    elif len(frac_part) > 2:
        raise ValueError("Fractional part must be at most 2 digits")

    if not frac_part.isdigit():
        raise ValueError(f"Invalid fractional part: {frac_part}")

    # Combine and format
    combined = f"{integer_part}.{frac_part}"

    if sign == '-':
        if integer_part == '0' and frac_part == '00':
            # Negative zero becomes zero
            return combined
        return f"-{combined}"
    else:
        return combined

