        s = s[1:]

    # Split on decimal point
    if '.' in s:
        int_part, frac_part = s.split('.', 1)
    else:
        int_part, frac_part = s, ''

    # Validate and normalize
    if not int_part:
        int_part = '0'
    if not frac_part:
        frac_part = '00'
    elif len(frac_part) == 1:
        frac_part = frac_part + '0'
    elif len(frac_part) > 2:
        raise ValueError("too many decimal places")

    # Ensure integer part is digits only
    if not int_part.isdigit():
        raise ValueError("invalid integer part")
    if not frac_part.isdigit() or len(frac_part) != 2:
        raise ValueError("invalid fractional part")

    # Combine into total cents (absolute value)
    cents = int(int_part) * 100 + int(frac_part)

    # Format with sign: '-' for negative, '' for zero/positive
    if sign == -1 and cents == 0:
        sign_str = ''
    elif sign == -1:
        sign_str = '-'
    else:
        sign_str = ''

    # Serialize as integer string with sign
    result = f"{sign_str}{cents}"
    return result

