def encode_amount(dollars: str) -> str:
    # validate and normalize
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")
    stripped = dollars.strip()
    if not stripped:
        raise ValueError("empty amount string")

    # handle optional leading sign
    sign = ''
    num_part = stripped
    if stripped[0] in ('+', '-'):
        sign = stripped[0]
        num_part = stripped[1:]
        if not num_part:
            raise ValueError(f"invalid amount: {dollars!r}")

    # must have at least one digit, optionally with a decimal point
    if '.' in num_part:
        integer_part, frac_part = num_part.split('.', 1)
        if not integer_part and not frac_part:
            raise ValueError(f"invalid amount: {dollars!r}")
        if len(frac_part) != 2:
            # always pad/round to exactly 2 decimal places
            if len(frac_part) < 2:
                frac_part = frac_part.ljust(2, '0')
            else:
                # round to 2 places (banker's rounding not required)
                frac_part = str(round(int(frac_part) / (10 ** (len(frac_part) - 2))))[:2].zfill(2)
    else:
        integer_part = num_part
        frac_part = '00'

    # remove leading zeros from integer part (but keep at least one digit)
    integer_part = integer_part.lstrip('0') or '0'

    # combine and encode
    if sign == '-':
        return f"({integer_part}.{frac_part})"
    else:
        return f"{integer_part}.{frac_part}"

