from __future__ import annotations


def encode_amount(dollars: str) -> str:
    """
    Encode a decimal dollar amount into the team's private wire format.

    Format: <sign><digits>#<check>
      - sign: '+' or '-'
      - digits: absolute amount in minor units/cents, with no decimal point
      - check: sum(decimal digits in digits) mod 10
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    sign_seen = False

    if s[0] in "+-":
        sign_seen = True
        negative = s[0] == "-"
        s = s[1:]

    if s.startswith("$"):
        s = s[1:]

    if not sign_seen and s and s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
        if "." in frac:
            raise ValueError("invalid amount")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if frac == "":
        frac = "0"

    if not whole.isdigit() or not frac.isdigit():
        raise ValueError("invalid amount")

    if len(frac) > 2:
        raise ValueError("amount has more than two decimal places")

    frac = frac.ljust(2, "0")
    digits = (whole + frac).lstrip("0") or "0"

    sign = "-" if negative and digits != "0" else "+"
    check = sum(ord(ch) - ord("0") for ch in digits) % 10

    return f"{sign}{digits}#{check}"

