from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = s.startswith("-")
    if s[0] in "+-":
        numeric = s[1:]
    else:
        numeric = s

    if not numeric:
        raise ValueError("invalid amount")

    try:
        value = Decimal(numeric)
    except InvalidOperation as exc:
        raise ValueError("invalid amount") from exc

    cents_decimal = (value * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    if cents_decimal != value * Decimal("100"):
        raise ValueError("amount must have at most two decimal places")

    cents = int(cents_decimal)
    if cents < 0:
        cents = -cents
        negative = True

    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10
    sign = "-" if negative else "+"

    return f"{sign}{digits}#{check}"

