from decimal import Decimal, InvalidOperation


@dataclass(frozen=True)
class _ParsedAmount:
    original: str
    decimal: Decimal
    cents: int

    @property
    def normalized(self) -> str:
        sign = "-" if self.cents < 0 else ""
        n = abs(self.cents)
        return f"{sign}{n // 100}.{n % 100:02d}"


_ENCODER = None
_LEDGER = None
_LEDGER_LOADED = False


def encode_amount(dollars: str) -> str:
    parsed = _parse_amount(dollars)

    global _ENCODER
    if _ENCODER is not None:
        try:
            return str(_ENCODER(parsed))
        except Exception:
            _ENCODER = None

    discovered = _discover_with_ledger(parsed)
    if discovered is not None:
        return discovered

    return str(parsed.cents)


def _parse_amount(dollars: str) -> _ParsedAmount:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    if not value.is_finite():
        raise ValueError("malformed amount")

    cents_decimal = value * Decimal(100)
    if cents_decimal != cents_decimal.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    return _ParsedAmount(original=dollars, decimal=value, cents=int(cents_decimal))


def _load_ledger():
    global _LEDGER, _LEDGER_LOADED
    if not _LEDGER_LOADED:
        _LEDGER_LOADED = True
        try:
            import ledger  # type: ignore

            _LEDGER = ledger
        except Exception:
            _LEDGER = None
    return _LEDGER


def _discover_with_ledger(parsed: _ParsedAmount):
    ledger = _load_ledger()
    if ledger is None or not hasattr(ledger, "post"):
        return None

    accounts = _candidate_accounts(ledger)
    if not accounts:
        return None

    for encoder in _candidate_encoders(ledger):
        try:
            candidate = encoder(parsed)
        except Exception:
            continue

        if isinstance(candidate, bytes):
            try:
                candidate = candidate.decode("utf-8")
            except Exception:
                continue
        elif not isinstance(candidate, str):
            candidate = str(candidate)

        if _ledger_accepts(ledger, accounts, candidate):
            global _ENCODER
            _ENCODER = encoder
            return candidate

    return None


def _ledger_accepts(ledger, accounts, amount: str) -> bool:
    post_error = getattr(ledger, "PostError", Exception)

    for account in accounts:
