from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def encode_amount(dollars: str) -> str:
    s = str(dollars).strip()

    sign = "+"
    if s.startswith(("+", "-")):
        if s[0] == "-":
            sign = "-"
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if "," in s:
        s = s.replace(",", "")

    try:
        value = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError(f"invalid money amount: {dollars!r}") from exc

    cents_decimal = (value * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    if cents_decimal != value * Decimal("100"):
        raise ValueError(f"money amount has more than two decimal places: {dollars!r}")

    cents = int(abs(cents_decimal))
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    if cents == 0:
        sign = "-"

    return f"{sign}{digits}#{check}"

