def encode_amount(dollars: str) -> str:
    s = dollars.strip()

    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    else:
        sign = '+'
        if s.startswith('+'):
            s = s[1:]

    s = s.replace('$', '')

    if '.' in s:
        whole, frac = s.split('.')
        if not whole:
            whole = '0'
        frac = (frac + '00')[:2]
        cents = int(whole) * 100 + int(frac)
    else:
        if not s:
            s = '0'
        cents = int(s) * 100

    digits = str(cents)
    check = sum(int(d) for d in digits) % 10

    return f"{sign}{digits}#{check}"

