import re


_AMOUNT_RE = re.compile(r"^(?P<whole>\d*)(?:\.(?P<frac>\d*))?$")


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"

    if s[0] in "+-":
        sign = s[0]
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if s and s[0] in "+-":
        sign = s[0]
        s = s[1:].strip()

    match = _AMOUNT_RE.match(s)
    if not match:
        raise ValueError("invalid amount")

    whole = match.group("whole")
    frac = match.group("frac")

    if whole == "" and (frac is None or frac == ""):
        raise ValueError("invalid amount")

    if frac is None:
        frac = "00"
    elif len(frac) == 0:
        frac = "00"
    elif len(frac) == 1:
        frac = frac + "0"
    elif len(frac) == 2:
        pass
    else:
        raise ValueError("too many fractional digits")

    cents = int(whole or "0") * 100 + int(frac)
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

