from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN


def encode_amount(dollars: str) -> str:
    try:
        value = Decimal(dollars)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError(f"malformed amount: {dollars!r}")

    cents = value * Decimal("100")
    if cents != cents.to_integral_value():
        raise ValueError(f"too many fractional digits: {dollars!r}")

    cents_int = int(cents.to_integral_value(rounding=ROUND_HALF_EVEN))
    return str(cents_int)

