import re


_AMOUNT_RE = re.compile(r"^([+-]?)(?:(\d+)(?:\.(\d{1,2}))?|\.(\d{1,2}))$")


def _bad_amount(message: str):
    try:
        from ledger import PostError
    except Exception:
        raise ValueError(message)
    raise PostError(message)


def encode_amount(dollars: str) -> str:
    """
    Serialize a dollar amount to the private wire representation: integer cents
    encoded as a base-10 string.
    """
    if not isinstance(dollars, str):
        _bad_amount("amount must be a string")

    match = _AMOUNT_RE.match(dollars)
    if not match:
        _bad_amount("malformed amount")

    sign, whole, frac_a, frac_b = match.groups()
    whole = whole or "0"
    frac = frac_a if frac_a is not None else frac_b
    frac = (frac or "").ljust(2, "0")

    cents = int(whole) * 100 + int(frac or "0")
    if cents == 0:
        return "0"

    return ("-" if sign == "-" else "") + str(cents)

