from decimal import Decimal, InvalidOperation


def encode_amount(dollars: str) -> str:
    s = str(dollars).strip()
    if not s:
        raise ValueError("empty amount")

    explicit_sign = ""

    if s[0] in "+-":
        explicit_sign = s[0]
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    if not explicit_sign and s and s[0] in "+-":
        explicit_sign = s[0]
        s = s[1:].strip()

    s = s.replace(",", "")

    if explicit_sign:
        s = explicit_sign + s

    try:
        amount = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("invalid amount") from exc

    if not amount.is_finite():
        raise ValueError("invalid amount")

    cents = amount * Decimal(100)

    if cents != cents.to_integral_value():
        raise ValueError("amount has more than two decimal places")

    sign = "-" if cents.is_signed() else "+"
    digits = str(abs(int(cents)))
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

