_AMOUNT_RE = re.compile(r"^\s*([+-]?)(?:(\d+)(?:\.(\d{1,2}))?|\.(\d{1,2}))\s*$")


def _raise_malformed(message: str):
    try:
        import ledger  # type: ignore

        raise ledger.PostError(message)
    except ImportError:
        raise ValueError(message)


def encode_amount(dollars: str) -> str:
    match = _AMOUNT_RE.match(dollars)
    if not match:
        _raise_malformed("malformed amount")

    sign, whole, frac_a, frac_b = match.groups()
    whole = whole or "0"
    frac = (frac_a if frac_a is not None else frac_b) or "0"
    cents = int(whole) * 100 + int(frac.ljust(2, "0"))

    if sign == "-" and cents != 0:
        cents = -cents

    return str(cents)

