    if not isinstance(dollars, str):
        raise ValueError("amount must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("amount is empty")

    negative = False
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        negative = True
        s = s[1:]

    if not s:
        raise ValueError("amount has no digits")

    if '.' in s:
        int_part, frac_part = s.split('.', 1)
    else:
        int_part, frac_part = s, ''

    if int_part and not int_part.isdigit():
        raise ValueError("amount has invalid integer part")
    if frac_part and not frac_part.isdigit():
        raise ValueError("amount has invalid fractional part")
    if len(frac_part) > 2:
        raise ValueError("amount has too many fractional digits")
    if not int_part and not frac_part:
        raise ValueError("amount has no digits")

    whole = int(int_part) if int_part else 0
    frac = int(frac_part.ljust(2, '0')) if frac_part else 0
    cents = whole * 100 + frac

    if negative:
        cents = -cents

