def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("Empty amount")

    sign = '-' if s.startswith('-') else '+'
    # Remove sign, currency symbol, and thousands separators
    body = s.lstrip('+').lstrip('-').replace('$', '').replace(',', '')

    if '.' in body:
        integer_part, frac_part = body.split('.', 1)
        if len(frac_part) < 2:
            frac_part = frac_part + '0' * (2 - len(frac_part))
        elif len(frac_part) > 2:
            frac_part = frac_part[:2]
        minor_str = integer_part + frac_part
    else:
        minor_str = body + '00'

    # Normalize: strip leading zeros, but keep a single zero if needed
    minor_str = minor_str.lstrip('0')
    if not minor_str:
        minor_str = '0'

    check = sum(int(ch) for ch in minor_str) % 10
    return f"{sign}{minor_str}#{check}"

